bash: sleep 1 && python3 -c "
import os
port_hex = format(8080, '04X')
for pid_dir in os.listdir('/proc'):
    if not pid_dir.isdigit():
        continue
    for path in [f'/proc/{pid_dir}/net/tcp6', f'/proc/{pid_dir}/net/tcp']:
        try:
            with open(path) as f:
                for line in f:
                    parts = line.strip().split()
                    if len(parts) >= 4 and parts[1].endswith(f':{port_hex}') and parts[3] == '0A':
                        with open(f'/proc/{pid_dir}/cmdline') as cf:
                            cmd = cf.read().replace(chr(0), ' ')
                        print(f'PID={pid_dir}  cmdline={cmd}')
        except: pass
"

